static void pattern(unsigned char *p){for(uint32_t y=0;y<SH;y++)for(uint32_t x=0;x<SW;x++){float chk=((x/12+y/12)&1)?0.72f:0.22f;float diag=(float)y-(float)x*0.5625f-35.0f;float edge=fabsf(diag)<2.8f?1.0f:0.0f;size_t i=((size_t)y*SW+x)*4;p[i]=(unsigned char)(255*(edge?0.95f:chk));p[i+1]=(unsigned char)(255*(edge?0.16f:0.45f+0.22f*sinf(x*0.012f)));p[i+2]=(unsigned char)(255*(edge?0.08f:0.30f+0.2f*cosf(y*0.018f)));p[i+3]=255;}}
static void bilinear(const unsigned char *in,unsigned char *out){for(uint32_t y=0;y<OH;y++)for(uint32_t x=0;x<OW;x++){float fx=((x+0.5f)*SW/OW)-0.5f,fy=((y+0.5f)*SH/OH)-0.5f;int x0=(int)floorf(fx),y0=(int)floorf(fy);float tx=fx-x0,ty=fy-y0;if(x0<0)x0=0;if(y0<0)y0=0;int x1=x0+1<SW?x0+1:x0,y1=y0+1<SH?y0+1:y0;for(int c=0;c<4;c++){float a=in[((size_t)y0*SW+x0)*4+c]*(1-tx)+in[((size_t)y0*SW+x1)*4+c]*tx;float b=in[((size_t)y1*SW+x0)*4+c]*(1-tx)+in[((size_t)y1*SW+x1)*4+c]*tx;out[((size_t)y*OW+x)*4+c]=(unsigned char)(a*(1-ty)+b*ty+0.5f);}}}
static double mean_luma(const unsigned char*p){double s=0;for(size_t i=0;i<(size_t)OW*OH;i++)s+=(0.2126*p[i*4]+0.7152*p[i*4+1]+0.0722*p[i*4+2])/255.;return s/(OW*OH);}
static double mean_color_error(const unsigned char *a,const unsigned char *b){double ma[3]={0},mb[3]={0};for(size_t i=0;i<(size_t)OW*OH;i++)for(int c=0;c<3;c++){ma[c]+=a[i*4+c];mb[c]+=b[i*4+c];}double worst=0;for(int c=0;c<3;c++){ma[c]/=(double)OW*OH;mb[c]/=(double)OW*OH;double d=fabs(ma[c]-mb[c])/fmax(ma[c],1.0);if(d>worst)worst=d;}return worst;}
static double energy(const unsigned char*p){double s=0;for(uint32_t y=0;y<OH;y++)for(uint32_t x=0;x<OW;x++){size_t i=((size_t)y*OW+x)*4;if(x+1<OW){double d=(p[i]-p[i+4])/255.;s+=d*d;}if(y+1<OH){double d=(p[i]-p[i+OW*4])/255.;s+=d*d;}}return s/((double)OW*OH);}
static void png_side(const unsigned char*a,const unsigned char*b){FILE*f=fopen(OUTPUT_PNG,"wb");if(!f){perror(OUTPUT_PNG);exit(2);}png_structp p=png_create_write_struct(PNG_LIBPNG_VER_STRING,NULL,NULL,NULL);png_infop info=png_create_info_struct(p);if(setjmp(png_jmpbuf(p)))exit(2);png_init_io(p,f);png_set_IHDR(p,info,OW*2,OH,8,PNG_COLOR_TYPE_RGBA,PNG_INTERLACE_NONE,PNG_COMPRESSION_TYPE_DEFAULT,PNG_FILTER_TYPE_DEFAULT);png_write_info(p,info);unsigned char*row=malloc(OW*8);for(uint32_t y=0;y<OH;y++){memcpy(row,a+(size_t)y*OW*4,OW*4);memcpy(row+OW*4,b+(size_t)y*OW*4,OW*4);png_write_row(p,row);}png_write_end(p,NULL);free(row);png_destroy_write_struct(&p,&info);fclose(f);}
