 unsigned char *src=malloc((size_t)SW*SH*4),*ref=malloc((size_t)OW*OH*4),*got=malloc((size_t)OW*OH*4);pattern(src);bilinear(src,ref);Img si=image(SW,SH),mi=image(OW,OH),oi=image(OW,OH);VkDeviceMemory upload_mem,read_mem;VkBuffer upload=buffer((VkDeviceSize)SW*SH*4,VK_BUFFER_USAGE_TRANSFER_SRC_BIT,&upload_mem),read=buffer((VkDeviceSize)OW*OH*4,VK_BUFFER_USAGE_TRANSFER_DST_BIT,&read_mem);void*map;VK(vkMapMemory(device,upload_mem,0,VK_WHOLE_SIZE,0,&map));memcpy(map,src,(size_t)SW*SH*4);vkUnmapMemory(device,upload_mem);
