 LodosFsr1 fsr;VK(lodos_fsr1_create(&fsr,device,FSR_EASU_SPV,FSR_RCAS_SPV));VK(lodos_fsr1_record(&fsr,cmd,si.view,mi.view,oi.view,SW,SH,OW,OH,0.2f));barrier(cmd,oi.image,VK_IMAGE_LAYOUT_GENERAL,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,VK_ACCESS_SHADER_WRITE_BIT,VK_ACCESS_TRANSFER_READ_BIT,VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT);vkCmdCopyImageToBuffer(cmd,oi.image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,read,1,&(VkBufferImageCopy){.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1},.imageExtent={OW,OH,1}});VK(vkEndCommandBuffer(cmd));VkSubmitInfo sub={.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO,.commandBufferCount=1,.pCommandBuffers=&cmd};VK(vkQueueSubmit(queue,1,&sub,VK_NULL_HANDLE));VK(vkQueueWaitIdle(queue));VK(vkMapMemory(device,read_mem,0,VK_WHOLE_SIZE,0,&map));memcpy(got,map,(size_t)OW*OH*4);vkUnmapMemory(device,read_mem);
 double mref=mean_luma(ref),mout=mean_luma(got),eref=energy(ref),eout=energy(got),delta=mean_color_error(ref,got);if(delta>0.02||eout<=eref||mout<0.01){fprintf(stderr,"FSR1 check failed mean RGB relative delta %.5f mean %.5f energy ref %.6f out %.6f\n",delta,mout,eref,eout);return 1;}png_side(ref,got);printf("FSR1 ok gpu=%s dims=%ux%u mean_rgb_delta=%.5f gradient_energy=%.6f bilinear=%.6f\n",prop.deviceName,OW,OH,delta,eout,eref);
